    83→### 3. 배열 정렬 및 검색
    84→
    85→```freelang
    86→fn bubble_sort(arr: &mut i64[]) -> void {
    87→  let n = len(arr)
    88→  let mut i = 0
    89→  while i < n {
    90→    let mut j = 0
    91→    while j < n - i - 1 {
    92→      if arr[j] > arr[j + 1] {
    93→        let temp = arr[j]
    94→        arr[j] = arr[j + 1]
    95→        arr[j + 1] = temp
    96→      }
    97→      j = j + 1
    98→    }
    99→    i = i + 1
   100→  }
   101→}
   102→
   103→fn binary_search(arr: i64[], target: i64) -> i64 {
   104→  let mut left = 0
   105→  let mut right = len(arr) - 1
   106→
   107→  while left <= right {
   108→    let mid = (left + right) / 2
   109→    if arr[mid] == target {
   110→      return mid
   111→    } else if arr[mid] < target {
   112→      left = mid + 1
   113→    } else {
   114→      right = mid - 1
   115→    }
   116→  }
   117→  return -1
   118→}
   119→
   120→fn main() -> void {
   121→  let mut numbers: i64[] = [64, 34, 25, 12, 22, 11, 90]
   122→  println("Original: " + str(numbers))
   123→
   124→  bubble_sort(&mut numbers)
   125→  println("Sorted: " + str(numbers))
   126→
   127→  let index = binary_search(numbers, 22)
   128→  println("Index of 22: " + str(index))
   129→}
   130→```
