   138→```freelang
   139→fn calculate(a: f64, op: string, b: f64) -> f64 {
   140→  if op == "+" {
   141→    return a + b
   142→  } else if op == "-" {
   143→    return a - b
   144→  } else if op == "*" {
   145→    return a * b
   146→  } else if op == "/" {
   147→    if b == 0.0 {
   148→      println("Error: Division by zero")
   149→      return 0.0
   150→    }
   151→    return a / b
   152→  } else {
   153→    println("Unknown operator: " + op)
   154→    return 0.0
   155→  }
   156→}
   157→
   158→fn main() -> void {
   159→  let result1 = calculate(10.0, "+", 5.0)
   160→  println("10 + 5 = " + str(result1))
   161→
   162→  let result2 = calculate(10.0, "*", 3.0)
