   170→### 5. 문자열 분석
   171→
   172→```freelang
   173→fn count_vowels(s: string) -> i64 {
   174→  let mut count = 0
   175→  for i in range(len(s)) {
   176→    let c = s[i]
   177→    if c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u' ||
   178→       c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U' {
   179→      count = count + 1
   180→    }
   181→  }
   182→  return count
   183→}
   184→
   185→fn is_palindrome(s: string) -> bool {
   186→  let clean = str_to_lower(s)
   187→  let mut i = 0
   188→  let mut j = len(clean) - 1
   189→
   190→  while i < j {
   191→    if clean[i] != clean[j] {
   192→      return false
   193→    }
   194→    i = i + 1
   195→    j = j - 1
   196→  }
   197→  return true
   198→}
   199→
   200→fn main() -> void {
   201→  let text = "Hello World"
   202→  println("Text: " + text)
   203→  println("Vowels: " + str(count_vowels(text)))
   204→
   205→  let word1 = "racecar"
   206→  println(word1 + " is palindrome: " + str(is_palindrome(word1)))
   207→
   208→  let word2 = "hello"
   209→  println(word2 + " is palindrome: " + str(is_palindrome(word2)))
   210→}
   211→```
