   314→### 8. 동적 프로그래밍 (배낭 문제)
   315→
   316→```freelang
   317→fn knapsack(weights: i64[], values: i64[], capacity: i64) -> i64 {
   318→  let n = len(weights)
   319→  let mut dp: i64[][] = []
   320→
   321→  let mut i = 0
   322→  while i <= n {
   323→    let mut row: i64[] = []
   324→    let mut j = 0
   325→    while j <= capacity {
   326→      row.push(0)
   327→      j = j + 1
   328→    }
   329→    dp.push(row)
   330→    i = i + 1
   331→  }
   332→
   333→  i = 1
   334→  while i <= n {
   335→    let mut j = 1
   336→    while j <= capacity {
   337→      if weights[i - 1] <= j {
   338→        let include = values[i - 1] + dp[i - 1][j - weights[i - 1]]
   339→        let exclude = dp[i - 1][j]
   340→        if include > exclude {
   341→          dp[i][j] = include
   342→        } else {
   343→          dp[i][j] = exclude
   344→        }
   345→      } else {
   346→        dp[i][j] = dp[i - 1][j]
   347→      }
   348→      j = j + 1
   349→    }
   350→    i = i + 1
   351→  }
   352→
   353→  return dp[n][capacity]
   354→}
   355→
   356→fn main() -> void {
   357→  let weights: i64[] = [2, 3, 4, 5]
   358→  let values: i64[] = [3, 4, 5, 6]
   359→  let capacity = 8
   360→
   361→  let max_value = knapsack(weights, values, capacity)
   362→  println("Maximum value: " + str(max_value))
   363→}
   364→```
